params.command:
$ErrorActionPreference='Stop'
$root=(Resolve-Path "$env:USERPROFILE\HeavenBridge").Path
$wt=Join-Path $env:USERPROFILE 'HeavenWorktrees\hcp-pr140-exact'
if (Test-Path $wt) { git -C $root worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $root fetch --quiet origin refs/heads/agent/hcp-phase0-hardening-20260929-1138
git -C $root worktree add --detach $wt 00744de03f562b3c592988a161680057aa79c015
$code=0
try {
  Push-Location $wt
  python plugins/heaven-control-plane/verify.py
  if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE }
  if ($code -eq 0) { git diff --check; if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE } }
  if ($code -eq 0) { python -m py_compile plugins/heaven-control-plane/heaven_control_plane/*.py plugins/heaven-control-plane/heaven_control_plane/adapters/*.py plugins/heaven-control-plane/tests/test_vertical_slice.py; if ($LASTEXITCODE -ne 0) { $code=$LASTEXITCODE } }
  Pop-Location
} finally {
  try { Pop-Location } catch {}
  git -C $root worktree remove --force $wt 2>$null
}
if ($code -ne 0) { exit $code }
Write-Output 'HCP_PR140_VERIFY_OK'
Write-Output 'HEAD=00744de03f562b3c592988a161680057aa79c015'
